@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : int
}

class Car {
  + Seats : int
}

class Van {}

Vehicle "1" -- "*" Location
Driver "1" -- "*" Location
Truck <|-- Vehicle
Car <|-- Vehicle
Van <|-- Vehicle

Driver "0..1" -- "0..1" Truck
Driver "0..1" -- "0..1" Car
Driver "0..1" -- "0..1" Van

class Order {
  + Origin : Location
  + Destination : Location
  + AssignedDriver : Driver
  + ExecutionDate : date
}

Driver "1" -- "*" Order

@enduml

